pub fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Precondition: a.len() == b.len()
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );

    let mut result = Vec::with_capacity(a.len());
    for i in 0..a.len() {
        // By the problem statement, b[i] != 0
        result.push(a[i] % b[i]);
    }
    result
}

